def format_bytes(n):
    """Format a byte count as a human-readable size string.

    Args:
        n: Number of bytes

    Returns:
        Formatted string like '1.5 KB', '2.3 MB', etc.
    """
    if n < 1024:
        return f"{n} B"
    elif n < 1024 ** 2:
        return f"{n / 1024:.1f} KB"
    elif n < 1024 ** 3:
        return f"{n / (1024 ** 2):.1f} MB"
    else:
        return f"{n / (1024 ** 3):.1f} GB"

